SELECT COUNT(*) AS accepted_documents_with_active_account_and_chart FROM pattern_documents d JOIN users u ON u.id=d.user_id AND u.status='active' AND u.locale_source='user_confirmed' JOIN pattern_generation_claims g ON g.id=d.claim_id AND g.status='accepted' AND g.chart_fingerprint_hash=d.chart_fingerprint_hash WHERE EXISTS (SELECT 1 FROM chart_snapshots c JOIN birth_profiles b ON b.user_id=c.user_id AND b.version=c.profile_version AND b.status='active' WHERE c.user_id=d.user_id AND c.status='active') AND NOT EXISTS (SELECT 1 FROM pattern_ontology_releases r WHERE r.version=d.ontology_version AND r.status='recalled');
WITH latest AS (SELECT kind,status,granted_at,expires_at,policy_version,ROW_NUMBER() OVER(PARTITION BY user_id,kind ORDER BY version DESC,created_at DESC,id DESC) AS row_number FROM consents WHERE kind IN ('account_processing','pattern_generation')) SELECT kind,status,COUNT(*) AS count,SUM(CASE WHEN status='granted' AND granted_at IS NOT NULL AND (expires_at IS NULL OR expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) THEN 1 ELSE 0 END) AS current_unexpired_granted_count FROM latest WHERE row_number=1 GROUP BY kind,status;
SELECT COUNT(*) AS applied_migration_count,MAX(name) AS latest_migration FROM d1_migrations;
SELECT name FROM sqlite_master WHERE type='table' AND name IN ('pattern_portraits','pattern_portrait_jobs','pattern_portrait_assets','portrait_automation_grants','portrait_start_outbox','portrait_mesh_jobs','portrait_mesh_assets') ORDER BY name;
SELECT p.active_version,r.status,r.locale,r.bundle_hash,r.recalled_at,(SELECT COUNT(*) FROM pattern_ontology_pipeline_evidence e WHERE e.ontology_version=r.version) AS pipeline_evidence_count FROM pattern_ontology_pointer p LEFT JOIN pattern_ontology_releases r ON r.version=p.active_version;
SELECT COUNT(*) AS users_count FROM users;
SELECT COUNT(*) AS pattern_documents_count FROM pattern_documents;
SELECT status,COUNT(*) AS count FROM pattern_generation_claims GROUP BY status;
SELECT stage,COUNT(*) AS count FROM pattern_generation_jobs GROUP BY stage;
SELECT status,COUNT(*) AS count FROM codex_provider_jobs GROUP BY status;
